{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Sotalol, a beta-blocker with a beta-hydroxy amine and aromatic ring, has an absolute oral bioavailability of 90% in humans, supporting high F for the query's similar ethanolamine/aromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Labetalol, which shares the beta-hydroxy phenethylamine and amide/aromatic features with the query, has systemic bioavailability of 26% in healthy volunteers, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Metoprolol, a beta-blocker with an aryloxypropanolamine, has absolute oral bioavailability of 38-60% in humans, supporting high F despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Phenylpropanolamine, a simple phenylethanolamine, has absolute bioavailability of 61.9% in healthy volunteers, supporting high F for the query's phenylethanolamine moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Bevantolol, a beta-blocker with a phenethylamine and aryloxypropanolamine, has mean absolute bioavailability of 57% (range 26-98%), supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Atazanavir has oral bioavailability of 69% in humans, demonstrating that even complex polar molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental evidence from beta-blocker/agonist analogues sharing the ethanolamine/aryl scaffold shows oral bioavailability mostly 40-100%, with the lowest relevant value (labetalol) at 20-35%, still at or above the 20% threshold. Therefore the query is predicted to have F >=20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is provided.",
    "Some analogues show variable F due to first-pass metabolism, so the exact F for the query remains uncertain.",
    "Qualitative low-bioavailability entries are not threshold-specific and are outweighed by quantitative absolute F measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

